---
// Builds a small git repo whose `entire/checkpoints/v1` branch has the layout of real Entire
// checkpoints (DESIGN.md §"Entire checkpoint format"). Every JSON payload is a clone of a
// redacted real sample in tests/fixtures/samples/ with values overridden; no keys are invented.
//
//   bun tests/fixtures/make-fixture.ts <outDir> [--scenario basic|confound|revert|multisession] [--force]
//
// Ground truth (commit kinds, checkpoint → sessions → setup) is printed as JSON on stdout and
// saved to <outDir>/.git/roster-fixture.json. The output is deterministic: fixed author, dates and ids.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

export const SCENARIOS = ["basic", "confound", "revert", "multisession"] as const;
export type Scenario = (typeof SCENARIOS)[number];
export type SetupKey = "X" | "Y" | "Z";

export const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
export const SAMPLES_DIR = join(import.meta.dir, "samples");
const TRUTH_FILE = "roster-fixture.json";
const AUTHOR = { name: "Roster Fixture", email: "[REDACTED_EMAIL]" };
const BASE_TIME = Date.parse("2026-09-01T09:00:00Z");
const STEP_MS = 24 * 3600 * 1000;

const readSample = (name: string) => readFileSync(join(SAMPLES_DIR, name), "utf8");
const sampleJson = (name: string) => JSON.parse(readSample(name));
const sampleJsonl = (name: string) =>
  readSample(name)
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => JSON.parse(l));

const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
const clone = <T>(v: T): T => structuredClone(v);

/** sha256 of a rules file normalised per DESIGN.md: LF line endings, trimmed. */
export const rulesHash = (text: string) => sha256(text.replace(/\r\n?/g, "\n").trim());

const DEFAULT_RULES = "# Fixture rules\n\n- Write tests for what you build.\n";
const STRICT_RULES = DEFAULT_RULES + "- Run the full test suite before you finish.\n- Never modify existing tests.\n";
const AGENTS_RULES = "# Fixture agent rules\n\n- Keep changes small.\n";

interface SetupDef {
  agent: "Claude Code" | "Codex";
  model: string;
  /** Value written to metadata.json `model`; "" forces the transcript fallback, as in real data. */
  metadataModel: string;
  rulesPath: "CLAUDE.md" | "AGENTS.md";
  rules: string;
  identity?: { modelId: string; marketingName: string };
}

/** Three fake setups: different model and different rules file. */
export const SETUPS: Record<SetupKey, SetupDef> = {
  X: {
    agent: "Claude Code",
    model: "claude-opus-5-5",
    metadataModel: "claude-opus-5-5",
    rulesPath: "CLAUDE.md",
    rules: DEFAULT_RULES,
    identity: { modelId: "claude-opus-5-5[1m]", marketingName: "Opus 5.5 (1M context)" },
  },
  Y: {
    agent: "Claude Code",
    model: "claude-sonnet-5-5",
    metadataModel: "",
    rulesPath: "CLAUDE.md",
    rules: STRICT_RULES,
    identity: { modelId: "claude-sonnet-5-5", marketingName: "Sonnet 5.5" },
  },
  Z: {
    agent: "Codex",
    model: "gpt-6-astra",
    metadataModel: "",
    rulesPath: "AGENTS.md",
    rules: AGENTS_RULES,
  },
};

// ---------- plan ----------

interface SessionSpec {
  setup: SetupKey;
  /** Same key ⇒ same session_id: a session recurring across checkpoints. */
  key: string;
  prompts: string[];
}
interface FileSpec {
  path: string;
  lines: number;
}
type Step =
  | { kind: "init" }
  | { kind: "agent"; subject: string; sessions: SessionSpec[]; files: FileSpec[] }
  /** A checkpoint that no commit links to (session kept with commit_sha = null). */
  | { kind: "orphan-checkpoint"; sessions: SessionSpec[]; files: FileSpec[] }
  | { kind: "revert"; target: number }
  /** Human commit (no trailer) that rewrites some agent-added lines of the target step. */
  | { kind: "rework"; target: number; lines: number }
  /** Human commit that deletes ≥ 50% of the target's added lines without a revert message. */
  | { kind: "delete"; target: number }
  | { kind: "human"; subject: string; path: string };

const sess = (setup: SetupKey, key: string, ...prompts: string[]): SessionSpec => ({
  setup,
  key,
  prompts: prompts.map((p, i) => (i === 0 ? `[roster setup=${setup} task=${key}] ${p}` : p)),
});
const humanTail = (n: number): Step[] =>
  Array.from({ length: n }, (_, i) => ({
    kind: "human" as const,
    subject: `human: notes ${i + 1}`,
    path: `docs/notes-${i + 1}.md`,
  }));

function basicPlan(): Step[] {
  return [
    { kind: "init" },
    { kind: "agent", subject: "add alpha", sessions: [sess("X", "x1", "Add the alpha module.")], files: [{ path: "src/alpha.ts", lines: 30 }] },
    { kind: "agent", subject: "add beta", sessions: [sess("Y", "y1", "Add the beta module.", "yes")], files: [{ path: "src/beta.ts", lines: 20 }] },
---
// Shared contracts for every Roster module. Shapes follow docs/DESIGN.md §"Data model".
// Change minimally, and say so in your PR.

/** Evidence level printed next to every claim: A observational, B controlled replay, C forward. */
export type EvidenceLevel = "A" | "B" | "C";
export const EVIDENCE_LEVELS: readonly EvidenceLevel[] = ["A", "B", "C"] as const;

/** Failure taxonomy (DESIGN.md §"Grade"). */
export enum FailureCode {
  /** edited tests */
  F1 = "F1",
  /** never ran tests */
  F2 = "F2",
  /** suite regression */
  F3 = "F3",
  /** stopped early */
  F4 = "F4",
  /** loop, timeout or turn cap */
  F5 = "F5",
  /** environment or setup error; the task is excluded and resampled */
  F6 = "F6",
  /** off-scope edits */
  F7 = "F7",
}

/** Where a session row came from. */
export type SessionSource = "branch" | "git-refs";

/** One agent session, aggregated over all checkpoints it appears in. Table `sessions`. */
export interface Session {
  id: string;
  repo: string;
  checkpoint_id: string;
  harness: string;
  /** Resolved model, or "unknown" when neither metadata nor transcript records it. */
  model: string;
  /** sha256 of the normalised rules file; null when unknown, never a guess. */
  rules_hash: string | null;
  setup_id: string | null;
  tokens_in: number;
  tokens_out: number;
  cache_read: number;
  cache_write: number;
  /** null when the model's price is unknown. */
  cost_usd: number | null;
  n_user_prompts: number;
  first_prompt: string;
  /** null when no commit carries this session's checkpoint trailer. */
  commit_sha: string | null;
  started_at: string;
  ended_at: string;
  files: string[];
  entire_url: string | null;
  source: SessionSource;
}

export type OutcomeStatus = "mature" | "too_young";
export type Tercile = 1 | 2 | 3;

/** Score of one session. Metrics are null when status is too_young. Table `outcomes`. */
export interface Outcome {
  session_id: string;
  status: OutcomeStatus;
  survival: number | null;
  reverted: boolean | null;
  rework_human: number | null;
  rework_agent: number | null;
  unattended: boolean | null;
  tests_at_commit: boolean | null;
  difficulty: number | null;
  tercile: Tercile | null;
}

/** Setup = harness + model + rules_hash. Table `setups`. */
export interface Setup {
  id: string;
  harness: string;
  model: string;
  rules_hash: string | null;
  rules_path: string | null;
  label: string;
}

/** Coordinator plan. Table `plans`; `json` holds the serialised PlanBody. */
export interface Plan {
  id: string;
  review_id: string;
  json: string;
  rationale: string;
  created_at: string;
}

/** Body of plan.json (DESIGN.md §"Plan (coordinator)"). */
export interface PlanBody {
  suspect: string | null;
  /** Session ids, ≤ 12, stratified by tercile. */
  tasks: string[];
  /** Setup ids, ≤ 3 per iteration. */
  candidates: string[];
  budget_usd: number;
  stop_rules: string[];
  rationale: string;
}

export type ReplayVerdict =
  | "agent_error"
  | "no_changes"
  | "hidden_tests_failed"
  | "suite_failed"
  | "guardrail_flagged"
  | "pass";

/** One replay attempt of a task under a setup. Table `replays`. */
export interface Replay {
  id: string;
  plan_id: string;
  task_session_id: string;
  setup_id: string;
  attempt: number;
  isolation_proof: string;
  turns: number | null;
  duration_ms: number | null;
  cost_usd: number | null;
  hidden_pass: boolean | null;
  suite_pass: boolean | null;
  scope_ok: boolean | null;
  judge_equiv: boolean | null;
  failure_codes: FailureCode[];
  verdict: ReplayVerdict;
  transcript_ref: string | null;
  trace_url: string | null;
}

export type GateVerdict = "promote" | "reject";

/** Table `gate_decisions`. */
export interface GateDecision {
  id: string;
  plan_id: string;
  candidate: string;
  verdict: GateVerdict;
  reasons: string[];
  trace_url: string | null;
}

/** One pre-registered forward task run through both setups. Table `forward_pairs`. */
export interface ForwardPair {
  task_id: string;
  setup_old: string;
  setup_new: string;
  pass_old: boolean;
  pass_new: boolean;
  cost_old: number | null;
  cost_new: number | null;
  /** Which setup's change was merged, if any. */
  merged: "old" | "new" | null;
  /** Blind label assignment, e.g. { X: "old", Y: "new" }. */
  blind_labels: Record<string, "old" | "new">;
  seed: number;
}

export type ReviewLabel = "suspect" | "no_suspect" | "insufficient_data";

/** One setup's row in a review. Rates are fractions in [0, 1] over mature sessions, null when there are none. */
export interface SetupRow {
  setup_id: string;
  label: string;
  harness: string;
  model: string;
  rules_hash: string | null;
  sessions: number;
  mature_sessions: number;
  /** Σ known session cost; 0 when no session is priced. */
  spend_usd: number;
  unattended: number | null;
  survival: number | null;
  reverted: number | null;
  rework_human: number | null;
  /** Σ survival over mature sessions. */
  surviving_changes: number;
  cost_per_surviving_change: number | null;
  evidence_level: EvidenceLevel;
}

/** Ground-truth prompt tags (`[roster setup=<tag> ...]`) against the setup ids Roster inferred. */
export interface ReviewTags {
  by_tag: Record<string, { sessions: number; setup_ids: string[] }>;
  tag_accuracy: number | null;
}

/** Difficulty-matched scorecard result (DESIGN.md §"Difficulty and review"). */
export interface Review {
  id: string;
  /** "owner/name" */
  repo: string;
  created_at: string;
  generated_at: string;
  has_entire_data: boolean;
  setups: SetupRow[];
  /** Present only when sessions carry prompt tags. */
  tags?: ReviewTags;
  label: ReviewLabel;
  /** Setup id when label is "suspect". */
  suspect: string | null;
  /** Mantel–Haenszel odds ratio, setup X vs the rest, stratified by tercile. */
  odds_ratio: number | null;
  ci95: [number, number] | null;
  p_value: number | null;
  evidence_level: EvidenceLevel;
}

